_etime_seconds() {
  local t=$1 d=0 h=0 m=0 s=0
  local -a parts
  if [[ $t == *-* ]]; then d=${t%%-*}; t=${t#*-}; fi
  parts=(${(s.:.)t})
  case ${#parts} in
    3) h=$parts[1]; m=$parts[2]; s=$parts[3] ;;
    2) m=$parts[1]; s=$parts[2] ;;
    1) s=$parts[1] ;;
  esac
  echo $(( ((d * 24 + h) * 60 + m) * 60 + s ))
}

