    """(number, line) for lines outside code fences and tables."""
    fenced = False
    for n, line in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
        if line.lstrip().startswith("```"):
            fenced = not fenced
            continue
        if not fenced and not line.lstrip().startswith("|"):
            yield n, line


for doc, width in WIDTH.items():
    path = Path(doc)
    tracked = subprocess.run(["git", "ls-files", "--error-unmatch", doc], capture_output=True).returncode == 0
    if tracked:   # only lines this change adds
        diff = subprocess.run(["git", "diff", "-U0", "--", doc], capture_output=True, text=True, check=True).stdout
        added = set()
        for hunk in re.finditer(r"^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@", diff, flags=re.M):
            start, count = int(hunk.group(1)), int(hunk.group(2) or 1)
            added.update(range(start, start + count))
    for n, line in prose_lines(path):
        if (not tracked or n in added) and len(line) > width:
            print(f"{doc}:{n}: {len(line)} characters > {width}")
            problems += 1
    for n, line in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
        for target in re.findall(r"\]\(([^)#]+)(?:#[^)]*)?\)", line):
            if not target.startswith(("http://", "https://")) and not (path.parent / target).exists():
                print(f"{doc}:{n}: missing link target {target}")
                problems += 1

private_plan = re.compile("implementation" + "[-_ ]" + "plan", re.I)
home = re.compile(r"/Users/|/home/")
email = re.compile(r"[\w.+-]+@[\w-]+\.[a-z]{2,}", re.I)
cjk = re.compile("[" + chr(0x3040) + "-" + chr(0x30FF) + chr(0x4E00) + "-" + chr(0x9FFF) + chr(0xAC00) + "-"
                 + chr(0xD7AF) + "]")
for f in FILES:
    for n, line in enumerate(Path(f).read_text(encoding="utf-8").splitlines(), 1):
        for name, rx in (("private-plan reference", private_plan), ("home path", home), ("email", email), ("CJK", cjk)):
            if rx.search(line) and not (name == "email" and "noreply@anthropic.com" in line):
                print(f"{f}:{n}: {name}")
                problems += 1
print("problems:", problems)
sys.exit(1 if problems else 0)

